// Real listings ported from the live embellishantiques.com (Wix) storefront
// on 2026-09-19. Names, categories, and prices were pulled directly from the
// site. Photos were pulled on 2026-09-25 by crawling the live shop's 13
// product-grid pages (to get each listing's exact product-page slug — a
// naive slugify(name) guess misses at least one, which lives at a
// "copy-of-<slug>" URL) and then reading each product page's server-rendered
// gallery for its full-resolution static.wixstatic.com/media/<id>~mv2.<ext>
// image URLs (the /v1/fill/... suffix is a Wix on-the-fly resize; the CDN
// still serves the original at that base URL with no suffix at all).
//
// Descriptions and measurements were pulled on 2026-09-25 by re-crawling
// every live product page's rich-text description block and parsing out the
// owner's freeform prose plus any ad-hoc "DIMENSIONS" / "CONDITION NOTES" /
// seat-measurement labels he typed directly into it (formatting is
// inconsistent listing to listing — some have labeled specs, some only have
// measurements woven into a sentence, and a handful have no description at
// all — `placeholderDescription` below is the fallback for that last case).
// `dimensions` is only populated where a real height was recoverable, since
// that's what the size-at-a-glance comparison on the product page needs.
//
// Two categories (Seating, Garden) don't list prices on the live site at
// all (common for made-to-inquire antique pricing) — priceCents is 0 for
// those and the UI shows "Price upon request" instead of a dollar amount.
// Mirrors currently has zero live listings.

import type { Category, Product, ProductImage } from "@/lib/types";

interface RawListing {
  name: string;
  category: Category;
  priceCents: number; // 0 = "price upon request"
  description?: string; // real listing copy pulled from the live site; falls back to placeholderDescription() when absent
  dimensions?: string; // e.g. `34"W × 22"D × 30"H`, only present where the live listing gave a recoverable height
  condition?: string;
  images: string[]; // full-res static.wixstatic.com URLs, in gallery order
}

