function slugify(name: string): string {
  return name
    .toLowerCase()
    .replace(/['’]/g, "")
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "");
}

function placeholderDescription(name: string, category: Category): string {
  return `${name} — a hand-selected piece from Embellish Antiques' ${category.toLowerCase()} collection. Full condition notes, provenance, and dimensions coming soon; replace this placeholder with the owner's original listing copy.`;
}

export const portedProducts: Product[] = RAW.map((item, index) => {
  const slug = slugify(item.name);
  const id = `ported-${index + 1}`;
  const images: ProductImage[] = item.images.map((url, position) => ({
    id: `${id}-img-${position + 1}`,
    productId: id,
    url,
    position,
  }));
  return {
    id,
    slug,
    name: item.name,
    description: item.description ?? placeholderDescription(item.name, item.category),
    priceCents: item.priceCents,
    category: item.category,
    dimensions: item.dimensions,
    condition: item.condition,
    images,
    status: "available",
    isNewArrival: false,
    likeCount: 0,
    viewCount: 0,
    clickCount: 0,
    createdAt: new Date("2026-09-01").toISOString(),
  };
});
